export function merge_intervals(xs: number[][]): number[][] {
  const sorted = xs.map((iv) => [iv[0], iv[1]]).sort((a, b) => a[0] - b[0]);
  const out: number[][] = [];
  for (const iv of sorted) {
    const last = out[out.length - 1];
    if (last !== undefined && iv[0] <= last[1]) {
      last[1] = Math.max(last[1], iv[1]);
    } else {
      out.push([iv[0], iv[1]]);
    }
  }
  return out;
}
